-- Din Felsefesi I: her hafta paketine 20 Zapoot ve 20 Quiz sorusu eklenir (aynı soru metni varsa atlanır).
-- Zapoot soruları 20, quiz soruları 60 saniye süreyle eklenir. Kaynak: docs/soru-onerileri/kaynak, üreten: scripts/soru-kontrol.py.
do $$
declare v_icerik uuid;
begin
  select id into v_icerik from public.subjects where ad = 'Din Felsefesi I' limit 1;
  if v_icerik is null then raise exception 'Din Felsefesi I içeriği bulunamadı'; end if;
  insert into public.questions (subject_id, soru, dogru, yanlislar, sure_sn, ek)
  select v_icerik, '"Din felsefesi" terimi felsefe literatürüne hangi eserle girmiştir?', 'Hegel''in 1832 tarihli eseriyle', array['Kant''ın 1781 tarihli eseriyle', 'Descartes''ın 1637 tarihli eseriyle', 'Platon''un Devlet diyaloğuyla'], 20, '{"paket": "1. hafta: Hızlı Zapoot (20 kısa soru)", "konu": "Terimin kökeni", "zorluk": "kolay", "bloom": "Hatırlama"}'::jsonb
  where not exists (select 1 from public.questions q where q.subject_id = v_icerik and lower(q.soru) = lower('"Din felsefesi" terimi felsefe literatürüne hangi eserle girmiştir?'));
